"""Build the second, food-brand-focused exploration collection."""
from pathlib import Path
from html import escape
import json,re
R=Path(__file__).resolve().parents[1]
E=R/'explorations/round-02'
D=json.loads((E/'directions.json').read_text())
STYLES={
 'rice-club':{'device':'One original rice-grain character, repeated in a small family of clear poses.','type':'Sturdy friendly display lettering; simple sans-serif information.','material':'Cream tubs, blue paper carriers and small yellow sticker accents.','copy':'Come hungry. Bring good company.','why':'A character can carry social posts and small printed extras without requiring a new logo for each campaign.'},
 'dum-block':{'device':'Broad red fields and a disciplined stripe rhythm, always leaving a clean zone for order information.','type':'Custom heavy uppercase wordmark; compact neutral information text.','material':'Red-and-cream carriers, cream tubs, a restrained saffron sealing strip.','copy':'Big on flavour. Clear on the details.','why':'The wordmark supplies the recognition; packaging geometry extends its weight and rhythm.'},
 'bowl-d':{'device':'A compact D/bowl symbol and generous two-colour fields.','type':'Bold quiet sans-serif wordmark; ample space around the small symbol.','material':'Forest paper panels, lime seals and cream labels.','copy':'A little mark. A generous welcome.','why':'The compact symbol is designed for avatars and seals, with the full name carrying recognition on larger surfaces.'},
 'grain-press':{'device':'An original rice-ear drawing with broad ink cuts, paired with a restrained editorial grid.','type':'Warm condensed serif display lettering; calm sans-serif operational copy.','material':'Uncoated cream paper, forest ink and terracotta illustration panels.','copy':'Flavour in Every Layer.','why':'Illustration and paper treatment can make the brand feel considered while the name stays straightforward.'},
}

def shell(title,body):
 return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{escape(title)} — Dum E Odisha</title><link rel="icon" href="../../assets/logo/favicon.png"><link rel="stylesheet" href="../explorations.css"><link rel="stylesheet" href="round.css"></head><body><a class="skip" href="#main">Skip to content</a><header class="topbar"><a class="brand" href="../../index.html">DUM E ODISHA</a><nav class="toplinks" aria-label="Brand ideas"><a href="index.html">Round 02</a><a href="../index.html">Earlier ideas</a><a href="reference-study.html">Reference study</a></nav></header><main class="wrap" id="main">{body}<footer><a href="index.html">Compare the new ideas ←</a><span>Original explorations / 17 October 2026 / no route adopted</span></footer></main></body></html>'''

cards=''
for i,r in enumerate(D['routes']):
 slug=r['slug'];style=STYLES[slug]
 cards+=f'''<article class="route-card"><a href="{slug}.html" aria-label="View {r['name']}"><img src="assets/{slug}-logo.webp" alt="{r['name']} original Dum E Odisha logo"></a><span class="number">0{i+1} / {r['family'].upper()}</span><h2>{r['name']}</h2><p>{r['description']}</p><a class="view" href="{slug}.html">View logo & brand world ↗</a></article>'''
 others=''.join(f'<a class="route-next" href="{x["slug"]}.html">{x["name"]} ↗</a>' for x in D['routes'] if x['slug']!=slug)
 body=f'''<div class="intro"><p class="eyebrow">Food-brand explorations / 0{i+1}</p><h1>{r['name']}</h1><p class="lead">{r['description']}</p></div><div class="two-col"><div class="logo-stage route-logo"><img src="assets/{slug}-logo.webp" alt="Original {r['family'].lower()} Dum E Odisha logo"></div><div><span class="tag">{r['family']} / new alternative</span><h2>{r['mood'].replace(', ','.<br>',1)}.</h2><p>{r['reference']}</p><p class="note">{r['tradeoff']}</p><div class="links"><a href="assets/{slug}-logo.png" download>Logo source PNG ↓</a><a href="#brand-world">See the brand system ↓</a></div></div></div>
 <section class="section" id="brand-world"><p class="eyebrow">The identity, applied</p><h2>A whole visual world.</h2><p>{style['why']}</p><figure class="gallery-figure"><a href="assets/{slug}-brand.png"><img class="image-full" src="assets/{slug}-brand.webp" alt="{r['name']} brand board showing the logo, coordinated packaging, graphic motifs and colour direction"></a><figcaption>Generated identity and packaging concept. Click to inspect the full-resolution artwork. Mockup lettering is illustrative; the standalone logo is the route reference.</figcaption></figure><div class="links"><a href="assets/{slug}-brand.png" download>Download brand board PNG ↓</a><a href="assets/{slug}-logo.png" download>Download logo PNG ↓</a></div></section>
 <section class="section"><div class="two-col"><div><p class="eyebrow">A small system, with a clear idea</p><h2>What makes it<br>this direction.</h2><div class="swatch-row"><span class="swatch" style="background:{r['color']};color:#FFF6E7">{r['color']}</span><span class="swatch" style="background:{r['accent']};color:#12100E">{r['accent']}</span></div></div><dl class="system-rules"><dt>Graphic device</dt><dd>{style['device']}</dd><dt>Typography behavior</dt><dd>{style['type']}</dd><dt>Packaging direction</dt><dd>{style['material']}</dd><dt>Draft voice example</dt><dd>“{style['copy']}”</dd></dl></div></section>
 <section class="section"><h2>Why it belongs in this round.</h2><p>{r['reference']}</p><p>The full business name remains Dum E Odisha. The route name describes a creative direction, not a proposed rename. This is a distinct alternative to compare with the current and script-led ideas.</p><div class="links"><a href="reference-study.html">Read the close reference study ↗</a><a href="../index.html">Compare the earlier directions ↗</a></div><p class="note">Artwork is generated raster exploration, not an approved vector master or manufactured packaging. No recipe, ingredient sourcing, founding story or customer result is implied by the visual direction. Final selection, small-size refinement and production proofing remain separate steps.</p></section><section class="section"><h2>Keep exploring.</h2><div class="route-next-grid">{others}</div></section>'''
 (E/f'{slug}.html').write_text(shell(r['name'],body))

rows=''.join(f'<tr><td><a href="{r["slug"]}.html">{r["name"]}</a></td><td>{r["family"]}</td><td>{STYLES[r["slug"]]["device"]}</td><td>{r["tradeoff"]}</td></tr>' for r in D['routes'])
body=f'''<div class="intro"><p class="eyebrow">New / Food-brand explorations / Round 02</p><h1>Four ideas.<br>Four different personalities.</h1><p class="lead">A mascot, a bold wordmark, a compact symbol and a tactile illustrated identity. Each direction is developed for Dum E Odisha with its own packaging, graphic language and colour system.</p><div class="links"><a href="reference-study.html">What we studied in your screenshots ↗</a><a href="../index.html">Earlier logo & script explorations ↗</a></div></div><div class="route-grid">{cards}</div><section class="section"><h2>Compare the actual idea.</h2><div class="comparison-table"><table><thead><tr><th>Direction</th><th>What leads</th><th>System beyond the logo</th><th>Tradeoff</th></tr></thead><tbody>{rows}</tbody></table></div><p class="note">Choose a card to inspect that logo and brand world. All four are exploratory alternatives; no selection or replacement of the current identity is assumed.</p></section>'''
if (R/'explorations/dum-club-refinement/index.html').exists():
 body=body.replace('<div class="route-grid">','<p class="note">Also available: <a href="../dum-club-refinement/index.html">the focused Dum Club refinement</a>, preserving the owner’s original rounded name and lid while exploring negative space and measured golden-ratio layout.</p><div class="route-grid">',1)
(E/'index.html').write_text(shell('Four new food-brand directions',body))
guide=R/'index.html'
if guide.exists():
 page=guide.read_text()
 guide_cards=''.join(f'<article class="idea-card"><a href="explorations/round-02/{r["slug"]}.html"><img src="explorations/round-02/assets/{r["slug"]}-logo.webp" alt="{r["name"]} original Dum E Odisha logo"><span>{r["family"]}</span><h3>{r["name"]}</h3><p>Explore the logo & coordinated brand world ↗</p></a></article>' for r in D['routes'])
 fragment='<section id="food-round"><div class="section-head"><div><p class="eyebrow">Latest / Food-brand explorations / Round 02</p><h2>Four more ideas.<br>Four distinct personalities.</h2></div><p>A friendly rice host, a bold wordmark, a compact D/bowl symbol and an illustrated editorial identity. These original directions study the structure of your latest reference screenshots.</p></div><div class="idea-grid food-grid">'+guide_cards+'</div><div class="downloads"><a href="explorations/round-02/index.html">Compare the four new ideas ↗</a><a href="explorations/round-02/reference-study.html">What the screenshots informed ↗</a></div></section>'
 if 'id="food-round"' in page:page=re.sub(r'<section id="food-round">.*?</section>',lambda _:fragment,page,count=1,flags=re.S)
 else:page=page.replace('<main id="main">','<main id="main">'+fragment,1)
 page=page.replace('href="#ideas">Explore ideas','href="#food-round">Explore ideas')
 guide.write_text(page)
print('Built the round-02 collection and four individual brand pages.')
